import test from 'node:test';import assert from 'node:assert/strict';import {mkdtemp,mkdir,writeFile,rm,realpath} from 'node:fs/promises';import os from 'node:os';import path from 'node:path';
import {captureSources} from '../../dist/source/roots.js';import {SourceIndex} from '../../dist/source/typescript-index.js';import {references,dynamicEdges} from '../../dist/source/references.js';import {sliceSource} from '../../dist/source/slices.js';import {assertFresh} from '../../dist/source/invalidation.js';import {sourceMapping} from '../../dist/source/source-maps.js';
async function fixture(t){const root=await mkdtemp(path.join(os.tmpdir(),'cocos p4 refs '));t.after(()=>rm(root,{recursive:true,force:true}));await mkdir(path.join(root,'assets'));const source='export class View {\n count=0;\n onClick(){ this.count++; const event="go"; this.emit(event); }\n emit(name:string){}\n long(){\n'+Array.from({length:180},(_,i)=>'  // '+i+' '+('x'.repeat(75))).join('\n')+'\n return this.count;\n }\n}\n';await writeFile(path.join(root,'assets/View.ts'),source);return {root,source};}
test('symbol references are typed and dynamic calls remain explicitly unresolved',async t=>{const f=await fixture(t),index=new SourceIndex(await captureSources(f.root,{creatorVersion:'3.7.3'})),view=index.resolve('View');const result=references(index,view.id,'count');assert.equal(result.length,3);assert.ok(result.every(r=>r.confidence==='semantic-symbol'));assert.ok(dynamicEdges(index).some(e=>e.reason==='dynamic-event-name'));});
test('paged method slices recover every character with revision/hash guard and no repeated or lost lines',async t=>{const f=await fixture(t),capture=await captureSources(f.root,{creatorVersion:'3.7.3'}),index=new SourceIndex(capture);const method=index.method(index.resolve('View').id,'long');let offset=0,text='';do{const page=sliceSource(capture,method.location.uri,method.location.hash,{start:method.location.range.start.offset,end:method.location.range.end.offset,offset});assert.ok(page.text.length<=6000);text+=page.text;offset=page.nextOffset;}while(offset!==null);assert.equal(text,f.source.slice(method.location.range.start.offset,method.location.range.end.offset));await writeFile(path.join(f.root,'assets/View.ts'),'\n'+f.source);await assert.rejects(assertFresh(capture),e=>e.code==='STALE_REVISION');});
test('source maps expose only captured original locations; absent/outside maps stay explicit',async t=>{const f=await fixture(t);let js=path.join(f.root,'assets/compiled.js');await writeFile(js,'var x=1;\n//# sourceMappingURL=compiled.js.map');await writeFile(js+'.map',JSON.stringify({version:3,sources:['View.ts'],names:[],mappings:'AAAA'}));const capture=await captureSources(f.root,{creatorVersion:'3.7.3'});js=await realpath(js);assert.equal(sourceMapping(capture,js,1,1).status,'mapped');await writeFile(js+'.map',JSON.stringify({version:3,sources:['../../outside.ts'],names:[],mappings:'AAAA'}));const denied=sourceMapping(await captureSources(f.root,{creatorVersion:'3.7.3'}),js,1,1);assert.equal(denied.status,'source-unavailable');assert.equal(sourceMapping(capture,path.join(capture.root,'assets/View.ts'),1,1).status,'no-source-map');});
test('typed reference filtering follows renamed imports and rejects unrelated same-spelling fields',async t=>{const f=await fixture(t);await writeFile(path.join(f.root,'assets/Other.ts'),'import {View as Alias} from "./View"; export class Other {count=2; run(v:Alias){return this.count+v.count;} }');const index=new SourceIndex(await captureSources(f.root,{creatorVersion:'3.7.3'})),view=index.resolve('View');assert.ok(references(index,view.id).some(r=>r.name==='Alias'));assert.equal(references(index,view.id,'count').length,4);});
